A Uniswap v4 hook: # JOB ORDER: SigmaHook v2 — Remove Vault, Add Operator Parameters
# REPO: github.com/identity-md-launches/launch-2658-sigmahook
# BRANCH: main

## 1. Delete
- src/SigmaVault.sol (entire file)
- All references to SigmaVault, vault(), svSHK, vTokenShares in src/SigmaHook.sol
- Any test files referencing vault, svSHK, or ERC4626
- Keep: src/SigmaMath.sol, src/PermanentTokenLock.sol, src/SigmaToken.sol, src/libraries/ (all)

## 2. Add to src/SigmaHook.sol (replace REBALANCE_INTERVAL constant)

Remove:
    uint256 public constant REBALANCE_INTERVAL = 30 minutes;

Add:
    uint8 public triggerSigma = 15;   // 1.5σ in tenths
    uint8 public rangeSigma = 30;     // 3.0σ in tenths
    uint32 public cooldown = 1800;    // 30 min in seconds

    struct Preset { uint8 trigger; uint8 range; uint32 cooldown; }
    Preset[6] public presets;

    // In constructor, after existing init:
    presets[0] = Preset(30, 30, 3600);   // SLEEP
    presets[1] = Preset(15, 20, 1800);   // STANDARD
    presets[2] = Preset(10, 15, 900);    // AGGRESSIVE
    presets[3] = Preset(5, 10, 300);     // MAX
    presets[4] = Preset(30, 40, 7200);   // DEFENSIVE
    presets[5] = Preset(255, 255, type(uint32).max); // PAUSED

    // New functions (all onlyOwner):
    function setMode(uint8 m) external onlyOwner {
        require(m < 6, "invalid mode");
        Preset memory p = presets[m];
        triggerSigma = p.trigger;
        rangeSigma = p.range;
        cooldown = p.cooldown;
        emit ModeChanged(m);
    }
    function setTriggerSigma(uint8 v) external onlyOwner {
        require(v >= 5 && v <= 50, "bounds");
        triggerSigma = v;
    }
    function setRangeSigma(uint8 v) external onlyOwner {
        require(v >= 10 && v <= 50, "bounds");
        rangeSigma = v;
    }
    function setCooldown(uint32 v) external onlyOwner {
        require(v >= 300 && v <= 86400, "bounds");
        cooldown = v;
    }
    function pause() external onlyOwner { triggerSigma = 255; }
    function resume() external onlyOwner { triggerSigma = presets[1].trigger; }

    // New events:
    event ModeChanged(uint8 mode);

## 3. Modify src/libraries/BandMath.sol

Change deviates() signature and body:
    function deviates(int24 tick, int256 sum, uint256 sigma8, uint256 triggerSigma) internal pure returns (bool) {
        int256 distance = int256(tick) * SAMPLES - sum;
        uint256 absolute = uint256(distance < 0 ? -distance : distance);
        return 10 * absolute > triggerSigma * sigma8;
    }

Change bands() signature and body:
    function bands(int256 sum, uint256 sigma8, int24 spacing, uint256 rangeSigma) internal pure returns (int24 lower, int24 upper) {
        int256 width = int256(int256(rangeSigma * sigma8 / 10));
        // ... rest unchanged
    }

## 4. Modify src/SigmaMath.sol

Update bands() wrapper to pass rangeSigma through:
    function bands(int256 sum, uint256 sigma8, int24 spacing, uint256 rangeSigma) external pure returns (int24 lower, int24 upper) {
        return BandMath.bands(sum, sigma8, spacing, rangeSigma);
    }

## 5. Update all call sites in SigmaHook.sol

- flashRebalance: replace REBALANCE_INTERVAL with cooldown
- flashRebalance: BandMath.deviates(tick, sum, sigma8) → BandMath.deviates(tick, sum, sigma8, triggerSigma)
- All math.bands(...) calls: add rangeSigma as 4th argument
- _afterInitialize: math.bands(int256(tick) * BandMath.SAMPLES, 0, key.tickSpacing) → add rangeSigma
- _rebalance: math.bands(sum, sigma8, _key.tickSpacing) → add rangeSigma
- _quoteDeposit: math.bands(sum, sigma8, _key.tickSpacing) → add rangeSigma
- proposedBands: math.bands(sum, sigma8, _key.tickSpacing) → add rangeSigma

## 6. Verify
forge build
forge test
forge fmt --check

All tests must pass. No ERC4626 references remaining. Push to main.

